    elseif($route==='results'){$conditions=[];$args=[];$q=trim((string)($_GET['q']??''));if($q!==''){$conditions[]='(nom LIKE ? OR ville LIKE ? OR telephone LIKE ? OR adresse LIKE ?)';array_push($args,"%$q%","%$q%","%$q%","%$q%");}if(!empty($_GET['phone']))$conditions[]="telephone IS NOT NULL AND telephone<>''";if(!empty($_GET['email']))$conditions[]="email IS NOT NULL AND email<>''";if(!empty($_GET['status'])){$conditions[]='statut_prospection=?';$args[]=$_GET['status'];}if(!empty($_GET['category'])){$conditions[]='categorie=?';$args[]=$_GET['category'];}$sql='SELECT * FROM prospects'.($conditions?' WHERE '.implode(' AND ',$conditions):'').' ORDER BY created_at DESC LIMIT 500';$st=db()->prepare($sql);$st->execute($args);$prospects=$st->fetchAll();$view='results';}
    elseif($route==='prospect'){$st=db()->prepare('SELECT * FROM prospects WHERE id=?');$st->execute([(int)($_GET['id']??0)]);$prospect=$st->fetch();if(!$prospect){http_response_code(404);$error='Prospect introuvable.';}else{$it=db()->prepare('SELECT i.*,u.nom user_name FROM interactions i JOIN users u ON u.id=i.user_id WHERE prospect_id=? ORDER BY date_interaction DESC');$it->execute([$prospect['id']]);$interactions=$it->fetchAll();}$view='prospect';}
    elseif($route==='map'){$prospects=db()->query('SELECT id,nom,categorie,ville,telephone,latitude,longitude,statut_prospection FROM prospects WHERE latitude IS NOT NULL AND longitude IS NOT NULL ORDER BY id DESC LIMIT 2000')->fetchAll();$view='map';}
    elseif($route==='kanban'){$rows=db()->query('SELECT id,nom,categorie,ville,telephone,statut_prospection FROM prospects ORDER BY updated_at DESC LIMIT 600')->fetchAll();$view='kanban';}
    elseif($route==='history'){$st=db()->prepare('SELECT s.*,u.nom user_name FROM searches s JOIN users u ON u.id=s.user_id ORDER BY s.created_at DESC LIMIT 100');$st->execute();$searches=$st->fetchAll();$view='history';}
    elseif($route==='settings'){$settings=[];foreach(db()->query('SELECT `cle`,`valeur` FROM settings')->fetchAll() as $r)$settings[$r['cle']]=$r['valeur'];$view='settings';}
    else{$view='dashboard';}
    include dirname(__DIR__).'/app/views/layout.php';
} catch(Throwable $ex){log_error($ex->__toString());if(str_starts_with($route,'api_'))json_response(['error'=>$ex instanceof PDOException?'Erreur de base de données. Vérifiez la configuration et le schéma.':$ex->getMessage()],500);http_response_code(500);$error='Une erreur est survenue : '.$ex->getMessage();$view='error';include dirname(__DIR__).'/app/views/layout.php';}
